# Domain classes
gro-au:FundingAllocation a owl:Class ;
    rdfs:subClassOf cco:Resource ;
    rdfs:label "Funding Allocation" ;
    skos:definition "A monetary resource allocated under a funding provision." .

gro-au:LargeProviderCondition a owl:Class ;
    rdfs:subClassOf cco:Condition ;
    rdfs:label "Large Provider Condition" ;
    skos:definition "A condition that applies when an approved course provider has more than 1,000 enrolments in a financial year." .

gro-au:NoEnrolmentCondition a owl:Class ;
    rdfs:subClassOf cco:Condition ;
    rdfs:label "No Enrolment Condition" ;
    skos:definition "A condition that applies when an approved course provider has no enrolments in a financial year." .

# Source entity
data:AUS_UNIT_00099 a prov:Entity ;
    rdfs:label "Source: AUS-UNIT-00099" .

# Subject: approved course provider (Organisation)
data:AUS_UNIT_00099_subject_de1c6b a cco:Organisation ;
    rdfs:label "Approved Course Provider" ;
    skos:definition "An organisation that is an approved course provider." ;
    prov:wasDerivedFrom data:AUS_UNIT_00099 .

# Action: is liable to pay
data:AUS_UNIT_00099_action_70829e a cco:Action ;
    rdfs:label "Liable to Pay" ;
    cco:hasActionExpression "is liable to pay" ;
    prov:wasDerivedFrom data:AUS_UNIT_00099 .

# Resource: $62,870 or minimum annual charge
data:AUS_UNIT_00099_object_b19ddb a gro-au:FundingAllocation ;
    rdfs:label "Funding Allocation Amount" ;
    skos:definition "$62,870 or the minimum annual charge" ;
    prov:wasDerivedFrom data:AUS_UNIT_00099 .

# Condition: large provider (more than 1,000 enrolments)
data:AUS_UNIT_00099_condition_7975f7 a gro-au:LargeProviderCondition ;
    rdfs:label "Large Provider Enrolment Condition" ;
    cco:hasConditionExpression "if the approved course provider is a large provider (more than 1,000 enrolments) for the financial year" ;
    prov:wasDerivedFrom data:AUS_UNIT_00099 .

# Condition: no enrolments
data:AUS_UNIT_00099_condition_no_enrol a gro-au:NoEnrolmentCondition ;
    rdfs:label "No Enrolment Condition" ;
    cco:hasConditionExpression "If there are no enrolments" ;
    prov:wasDerivedFrom data:AUS_UNIT_00099 .

# Norm: Obligation to pay
data:AUS_UNIT_00099_norm_08df8a a cco:Obligation ;
    rdfs:label "Large Provider Payment Obligation" ;
    gro:hasSubject data:AUS_UNIT_00099_subject_de1c6b ;
    cco:hasAction data:AUS_UNIT_00099_action_70829e ;
    cco:hasObject data:AUS_UNIT_00099_object_b19ddb ;
    cco:appliesUnder data:AUS_UNIT_00099_condition_7975f7 ;
    cco:appliesUnder data:AUS_UNIT_00099_condition_no_enrol ;
    prov:wasDerivedFrom data:AUS_UNIT_00099 .

