    rdfs:label "Source: CAN-UNIT-00016" .

data:CAN_UNIT_00016_norm_43dce7 a cco:Obligation ;
    rdfs:label "Institution Eligibility Obligation" ;
    gro:hasSubject data:CAN_UNIT_00016_subject_7d51f0 ;
    cco:hasAction data:CAN_UNIT_00016_action_8bfbc5 ;
    cco:appliesUnder data:CAN_UNIT_00016_condition_eligibility ;
    cco:hasException data:CAN_UNIT_00016_exception_208286 ;
    prov:wasDerivedFrom data:CAN_UNIT_00016 .

data:CAN_UNIT_00016_subject_7d51f0 a cco:Organisation ;
    rdfs:label "Institution" ;
    skos:definition "All institutions subject to this provision" ;
    skos:altLabel "All institutions" ;
    prov:wasDerivedFrom data:CAN_UNIT_00016 .

data:CAN_UNIT_00016_action_8bfbc5 a cco:Action ;
    rdfs:label "Meet Eligibility Criteria" ;
    cco:hasActionExpression "must meet the following three criteria: 1. offer and deliver at least one program that fully meets the program eligibility requirements; 2. grant a formal citation, certificate, diploma, or degree recognizing successful completion of a post-secondary program of study at the institution; 3. be in continuous operation for a minimum of two years immediately prior to designation, or 10 years for a medical institution located outside of North America and be in good standing with the appropriate educational accrediting, regulatory, or government body in the jurisdiction where it is located." ;
    prov:wasDerivedFrom data:CAN_UNIT_00016 .

data:CAN_UNIT_00016_condition_eligibility a cco:Condition ;
    rdfs:label "Eligibility Criteria Condition" ;
    cco:hasConditionExpression "Institutions regulated by a B.C. regulator must offer and deliver at least one program that fully meets the program eligibility requirements. Institutions regulated outside of B.C. may be eligible if they offer and deliver on-site at least one program that fully meets the program eligibility requirements. Grant a formal citation, certificate, diploma, or degree recognizing successful completion of a post-secondary program of study at the institution. Be in continuous operation for a minimum of two years immediately prior to designation, or 10 years for a medical institution located outside of North America and be in good standing with the appropriate educational accrediting, regulatory, or government body in the jurisdiction where it is located." ;
    prov:wasDerivedFrom data:CAN_UNIT_00016 .

data:CAN_UNIT_00016_exception_208286 a cco:Exception ;
    rdfs:label "BC Institution Two-Year Exemption" ;
    cco:modifiesNorm data:CAN_UNIT_00016_norm_43dce7 ;
    cco:hasCondition data:CAN_UNIT_00016_condition_exception ;
    prov:wasDerivedFrom data:CAN_UNIT_00016 .

data:CAN_UNIT_00016_condition_exception a cco:Condition ;
    rdfs:label "Ministerial Consent or Designation Certificate" ;
    cco:hasConditionExpression "Institutions operating in B.C. with ministerial consent under the Degree Authorization Act, or that have a valid Designation Certificate issued under the Private Training Act, are exempt from the two-year requirement." ;
    prov:wasDerivedFrom data:CAN_UNIT_00016 .

