data:UK_UNIT_00049 a prov:Entity ;
    rdfs:label "Source: UK-UNIT-00049" .

gro-uk:ApprenticeRole a owl:Class ;
    rdfs:subClassOf cco:Role ;
    rdfs:label "Apprentice Role" ;
    skos:definition "The role of an individual undertaking an apprenticeship, involving training and employment." .

