data:UK_UNIT_00054 a prov:Entity ;
    rdfs:label "Source: UK-UNIT-00054" .

gro-uk:StudentLoan a owl:Class ;
    rdfs:subClassOf cco:Resource ;
    rdfs:label "Student Loan" ;
    skos:definition "A loan provided to students to fund their education, which is prohibited from being used to pay for an apprenticeship under certain conditions." .

gro-uk:Apprenticeship a owl:Class ;
    rdfs:subClassOf cco:Action ;
    rdfs:label "Apprenticeship" ;
    skos:definition "A system of training a new generation of practitioners of a trade or profession with on-the-job training and often some accompanying study." .

data:UK_UNIT_00054_subject_98278f a cco:Role ;
    rdfs:label "Individual Role" ;
    skos:definition "The role of an individual who is subject to the prohibition on using a student loan to pay for their apprenticeship." ;
    prov:wasDerivedFrom data:UK_UNIT_00054 .

data:UK_UNIT_00054_object_407c43 a gro-uk:StudentLoan ;
    rdfs:label "Student Loan" ;
    skos:definition "A student loan that is prohibited from being used to pay for an apprenticeship." ;
    prov:wasDerivedFrom data:UK_UNIT_00054 .

data:UK_UNIT_00054_action_171bb0 a cco:Action ;
    rdfs:label "Use Student Loan for Apprenticeship" ;
    cco:hasActionExpression "does not use a student loan to pay for their apprenticeship" ;
    prov:wasDerivedFrom data:UK_UNIT_00054 .

data:UK_UNIT_00054_condition_7a2f3c a cco:Condition ;
    rdfs:label "Transfer from Loan-Funded Course" ;
    cco:hasConditionExpression "Where an individual transfers to an apprenticeship from a full-time further education or higher education course, and that course has been funded by a student loan, the loan must be terminated by the individual and the provider must be satisfied that this has occurred." ;
