data:UK_UNIT_00652 a prov:Entity ;
    rdfs:label "Source: UK-UNIT-00652" .

gro-uk:MainProvider a owl:Class ;
    rdfs:subClassOf cco:Organisation ;
    rdfs:label "Main Provider" ;
    skos:definition "An organisation that acts as a main provider of apprenticeship training under UK funding rules." .

gro-uk:CompletionPayment a owl:Class ;
    rdfs:subClassOf cco:Resource ;
    rdfs:label "Completion Payment" ;
    skos:definition "A payment made to a main provider upon completion of apprenticeship training, as described in paragraph 161." .

data:UK_UNIT_00652_subject_7b49a3 a gro-uk:MainProvider ;
    rdfs:label "Main Providers" ;
    skos:definition "Main providers eligible for the completion payment under non-levy funding conditions." ;
    prov:wasDerivedFrom data:UK_UNIT_00652 .

data:UK_UNIT_00652_object_9988d5 a gro-uk:CompletionPayment ;
    rdfs:label "Completion Payment" ;
    skos:definition "The completion payment described in paragraph 161, payable to eligible main providers." ;
    prov:wasDerivedFrom data:UK_UNIT_00652 .

data:UK_UNIT_00652_action_8c4840 a cco:Action ;
    rdfs:label "Meet Eligibility Conditions" ;
    cco:hasActionExpression "must have [conditions to be eligible for the completion payment]" ;
    prov:wasDerivedFrom data:UK_UNIT_00652 .

data:UK_UNIT_00652_condition_448aed a cco:Condition ;
    rdfs:label "Non-Levy Funding Condition" ;
    cco:hasConditionExpression "Where apprenticeship training is not funded from an employer’s levy funds (i.e. non-levy payers and levy payers with insufficient funds)" ;
    prov:wasDerivedFrom data:UK_UNIT_00652 .

data:UK_UNIT_00652_norm_d35176 a cco:Obligation ;
    rdfs:label "Completion Payment Eligibility Obligation" ;
    gro:hasSubject data:UK_UNIT_00652_subject_7b49a3 ;
    cco:hasAction data:UK_UNIT_00652_action_8c4840 ;
    cco:hasObject data:UK_UNIT_00652_object_9988d5 ;
    cco:appliesUnder data:UK_UNIT_00652_condition_448aed ;
