data:USA_UNIT_00184 a prov:Entity ;
    rdfs:label "Source: USA-UNIT-00184" .

gro-us:ParentsContribution a owl:Class ;
    rdfs:subClassOf cco:Resource ;
    rdfs:label "Parents' Contribution" ;
    skos:definition "The calculated amount representing the portion of parental income and assets considered available to help pay for the student's college education, as determined under the 2025-26 Student Aid Index (SAI) and Pell Grant Eligibility Guide." ;
    prov:wasDerivedFrom data:USA_UNIT_00184 .

data:USA_UNIT_00184_subject_814ac6 a gro-us:ParentsContribution ;
    rdfs:label "Parents' Contribution" ;
    skos:definition "The parents' contribution from assets and adjusted available income, calculated by multiplying discretionary net worth by 12%, adding available income, and applying rates from Table A5 (22% to 47%)." ;
    prov:wasDerivedFrom data:USA_UNIT_00184 .

data:USA_UNIT_00184_action_57e6aa a cco:Action ;
    rdfs:label "Calculate Parents' Contribution" ;
    cco:hasActionExpression "The parents' contribution from assets is calculated by multiplying discretionary net worth by the conversion rate of 12%, and if negative, it is set to zero. The parents' available income and contribution from assets are added together to determine the parents' adjusted available income. The total parents' contribution from adjusted available income is calculated from the amounts and rates in Table A5, where rates increase from 22% to 47% as adjusted available income increases." ;
    prov:wasDerivedFrom data:USA_UNIT_00184 .

data:USA_UNIT_00184_object_f000b7 a cco:Resource ;
    rdfs:label "Contribution from Assets and Adjusted Available Income" ;
    skos:definition "The parents' contribution from assets and adjusted available income, as defined in the 2025-26 Student Aid Index (SAI) and Pell Grant Eligibility Guide." ;
    prov:wasDerivedFrom data:USA_UNIT_00184 .

data:USA_UNIT_00184_condition_71eba7 a cco:Condition ;
    rdfs:label "Negative Contribution from Assets" ;
    cco:hasConditionExpression "If the contribution from assets is negative, it is set to zero." ;
    prov:wasDerivedFrom data:USA_UNIT_00184 .

data:USA_UNIT_00184_norm_afc253 a cco:Norm ;
    rdfs:label "Parents' Contribution Calculation Rule" ;
    skos:definition "Structural calculation rule defining how the parents' contribution is computed, including the 12% conversion rate, the addition of available income, and the application of Table A5 rates (22% to 47%), with a condition that negative asset contributions are set to zero." ;
    cco:hasAction data:USA_UNIT_00184_action_57e6aa ;
    cco:hasObject data:USA_UNIT_00184_object_f000b7 ;
    cco:appliesUnder data:USA_UNIT_00184_condition_71eba7 ;
    prov:wasDerivedFrom data:USA_UNIT_00184 .

